import React, { useEffect, useState } from 'react';
import getVotingContract from '../utils/getVotingContract';

const VotingPage = () => {
  const [candidates, setCandidates] = useState([]);
  const [hasVoted, setHasVoted] = useState(false);
  const [loading, setLoading] = useState(true);
  const [votedCandidateIndex, setVotedCandidateIndex] = useState(null);

  const [account, setAccount] = useState("");

  

  const handleVote = async (index) => {
    try {
      const contract = await getVotingContract();
      await contract.vote(index);
      setHasVoted(true); // Set local state

      // Update vote count
      const updatedCandidates = [...candidates];
      updatedCandidates[index].votes += 1;
      setCandidates(updatedCandidates);

    } catch (err) {
      console.error("Voting error:", err);
    }
  };

  if (loading) return <div>Loading candidates...</div>;

  return (
    <div className="container mt-4">
      <h2 className="mb-4">Vote for Your Candidate</h2>
      <table className="table table-bordered">
        <thead className="thead-dark">
          <tr>
            <th>#</th>
            <th>Name</th>
            <th>Votes</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody>
          {candidates.map((candidate, index) => (
            <tr key={index}>
              <td>{index + 1}</td>
              <td>{candidate.name}</td>
              <td>{candidate.votes}</td>
              <td>
                {hasVoted ? (
                  <button className="btn btn-secondary" disabled>Voted</button>
                ) : (
                  <button className="btn btn-success" onClick={() => handleVote(index)}>Vote</button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default VotingPage;
